from app.models import (
    Block,
    BlockType,
    Document,
    DocumentMetadata,
    PipelineDocument,
    TemplateInfo,
    TextStyle,
)

# SPDX-License-Identifier: MIT\n# Copyright (c) 2026 ScholarForm AI\n\n"""\nGap-filling tests for StructureDetector — covers uncovered branches, edge cases,\nand error paths not tested in existing deep suite.\n"""\n\nfrom __future__ import annotations\n\nimport pytest\nfrom unittest.mock import patch, MagicMock\nfrom app.pipeline.structure_detection.detector import StructureDetector, detect_structure\n\n\ndef _b(text: str, index: int = 1, font_size: float = 12.0, bold: bool = False,\n    from app.models.pipeline_document import DocumentMetadata, TemplateInfo\n        block_type: BlockType = BlockType.PARAGRAPH, **kwargs) -> Block:\n    style = TextStyle(font_size=font_size, bold=bold)\n    meta = kwargs.pop("metadata", {})\n    block = Block(\n        block_id=f"b{index}", text=text, index=index,\n        block_type=block_type, style=style, **kwargs\n    for k, v in meta.items():\n        block.metadata[k] = v\n    return block\n\n\ndef _make_doc(blocks: list | None = None, template_name: str | None = None,\n              docling_elements: list | None = None) -> PipelineDocument:\n    blocks = blocks or []\n    ai_hints = {}\n    if docling_elements is not None:\n        ai_hints["docling_layout"] = {"elements": docling_elements}\n    template = TemplateInfo(template_name=template_name) if template_name else None\n    return PipelineDocument(\n        document_id="test",\n        blocks=blocks,\n        metadata=DocumentMetadata(ai_hints=ai_hints),\n        template=template,\n\n\n@pytest.fixture(autouse=True)\ndef auto_normalize():\n    with patch("app.pipeline.normalization.normalizer.Normalizer.process", autospec=True) as mock:\n        mock.side_effect = lambda self_, doc: doc\n        yield mock\n\n\n@pytest.fixture\ndef detector():\n    return StructureDetector()\n\n\nclass TestCalculateAvgFontSize:\n    """Cover _calculate_avg_font_size edge cases."""\n\n    def test_no_blocks_with_font_size(self, detector):\n        """No blocks have font_size -> returns None."""\n        doc = _make_doc(blocks=[\n            _b("Text", 0, font_size=None),\n            _b("More", 1, font_size=None),\n        ])\n        result = detector.process(doc)\n        assert detector.avg_font_size is None\n\n    def test_mixed_font_size_blocks(self, detector):\n        """Some blocks with font_size, some without."""\n        b1 = _b("Title", 0, font_size=18)\n        b2 = _b("", 1, font_size=12)  # empty text, should be skipped\n        doc = _make_doc(blocks=[b1, b2])\n        result = detector.process(doc)\n        assert detector.avg_font_size == 18.0\n\n    def test_single_font_size(self, detector):\n        """Single font size value."""\n        doc = _make_doc(blocks=[_b("Hello", 0, font_size=14)])\n        result = detector.process(doc)\n        assert detector.avg_font_size == 14.0\n\n    def test_multiple_font_sizes_uses_median(self, detector):\n        """Median of font sizes (not mean)."""\n        doc = _make_doc(blocks=[\n            _b("Small", 0, font_size=10),\n            _b("Medium", 1, font_size=12),\n            _b("Large", 2, font_size=20),\n        ])\n        result = detector.process(doc)\n        assert detector.avg_font_size == 12.0\n\n\nclass TestBuildHierarchyGaps:\n    """Cover _build_hierarchy edge cases."""\n\n    def test_no_headings(self, detector):\n        """No heading candidates -> hierarchy is empty (no crash)."""\n        doc = _make_doc(blocks=[\n            _b("Just a body paragraph.", 0, font_size=12),\n            _b("Another paragraph.", 1, font_size=12),\n        ])\n        result = detector.process(doc)\n        assert result is not None\n\n    def test_sibling_headings(self, detector):\n        """Multiple headings at same level -> siblings, no parent."""\n        doc = _make_doc(blocks=[\n            _b("1. Introduction", 0, font_size=18),\n            _b("2. Methods", 1, font_size=18),\n            _b("3. Results", 2, font_size=18),\n        ])\n        result = detector.process(doc)\n        assert result is not None\n        for b in result.blocks:\n            assert b.parent_id is None\n\n    def test_deep_nesting(self, detector):\n        """Deep nesting: L1 -> L2 -> L3 -> L4."""\n        doc = _make_doc(blocks=[\n            _b("1. Top", 0, font_size=18),\n            _b("1.1 Mid", 1, font_size=16),\n            _b("1.1.1 Deep", 2, font_size=14),\n            _b("1.1.1.1 Deepest", 3, font_size=12),\n        ])\n        result = detector.process(doc)\n        assert result is not None\n        assert result.blocks[3].parent_id == result.blocks[2].block_id\n\n    def test_parent_change_when_level_goes_up(self, detector):\n        """When nesting level goes up, parent changes."""\n        doc = _make_doc(blocks=[\n            _b("1. Introduction", 0, font_size=18),\n            _b("1.1 Background", 1, font_size=16),\n            _b("2. Methods", 2, font_size=18),\n        ])\n        result = detector.process(doc)\n        assert result is not None\n        # Block 2 (L1) should have no parent (or parent None)\n        assert result.blocks[2].parent_id is None or result.blocks[2].parent_id == result.blocks[0].block_id\n\n\nclass TestAssignSectionNamesGaps:\n    """Cover _assign_section_names edge cases."""\n\n    def test_heading_without_numbering_info(self, detector):\n        """Section heading without numbering_info uses full text."""\n        doc = _make_doc(blocks=[\n            _b("Introduction", 0, font_size=18, bold=True),\n        ])\n        result = detector.process(doc)\n        assert result is not None\n        # First block may be detected as 'title' by detect_title rule\n        assert result.blocks[0].section_name in ("Introduction", "title")\n\n    def test_block_before_first_heading(self, detector):\n        """Block before first heading gets no section_name."""\n        doc = _make_doc(blocks=[\n            _b("Some preliminary text", 0, font_size=12),\n            _b("1. Introduction", 1, font_size=18),\n        ])\n        result = detector.process(doc)\n        assert result is not None\n        assert result.blocks[0].section_name is None or result.blocks[0].section_name == "title"\n\n    def test_heading_with_numbering_remainder(self, detector):\n        """Numbering remainder used for section_name."""\n        doc = _make_doc(blocks=[\n            _b("1.1. Background", 0, font_size=16),\n        ])\n        result = detector.process(doc)\n        assert result is not None\n        assert result.blocks[0].section_name == "Background"\n\n    def test_title_level_section_name(self, detector):\n        """Title level (0) gets section_name 'title'."""\n        doc = _make_doc(blocks=[\n            _b("Paper Title", 0, font_size=20),\n            _b("Body text", 1, font_size=12),\n        ])\n        result = detector.process(doc)\n        assert result is not None\n        assert result.blocks[0].section_name == "title" or result.blocks[0].section_name is None\n\n\nclass TestValidateHierarchyGaps:\n    """Cover _validate_hierarchy edge cases."""\n\n    def test_no_heading_blocks(self, detector):\n        """No heading blocks -> no validation warnings."""\n        doc = _make_doc(blocks=[\n            _b("Body text.", 0, font_size=12),\n        ])\n        result = detector.process(doc)\n        assert result is not None\n        assert len(result.blocks[0].warnings) == 0\n\n    def test_l1_to_l3_jump(self, detector):\n        """L1 to L3 jump adds warning."""\n        doc = _make_doc(blocks=[\n            _b("1. Introduction", 0, font_size=18, block_type=BlockType.HEADING_1),\n            _b("1.1.1 Deep", 1, font_size=14, block_type=BlockType.HEADING_1),\n        ])\n        result = detector.process(doc)\n        assert result is not None\n        h1 = result.blocks[1]\n        assert any("jump" in w.lower() for w in h1.warnings)\n\n    def test_l1_to_l2_no_jump(self, detector):\n        """L1 to L2 is valid."""\n        doc = _make_doc(blocks=[\n            _b("1. Introduction", 0, font_size=18, block_type=BlockType.HEADING_1),\n            _b("1.1 Sub", 1, font_size=16, block_type=BlockType.HEADING_1),\n        ])\n        result = detector.process(doc)\n        assert result is not None\n        assert len(result.blocks[1].warnings) == 0\n        assert result.blocks[1].is_valid is True\n\n    def test_header_skip_in_validation(self, detector):\n        """Header blocks are skipped in validation."""\n        doc = _make_doc(blocks=[\n            _b("1. Introduction", 0, font_size=18, block_type=BlockType.HEADING_1),\n            _b("Header", 1, font_size=10, metadata={"is_header": True}),\n            _b("1.1.1 Deep", 2, font_size=14, block_type=BlockType.HEADING_1),\n        ])\n        result = detector.process(doc)\n        assert result is not None\n        h2 = result.blocks[2]\n        assert any("jump" in w.lower() for w in h2.warnings)\n\n\nclass TestCanonicalizeSectionsGaps:\n    """Cover _canonicalize_sections remaining edge cases."""\n\n    def test_no_publisher_no_canonicalization(self, detector):\n        """No template -> no canonicalization."""\n        doc = _make_doc(blocks=[\n            _b("1. Introduction", 0, font_size=18),\n        ])\n        with patch.object(detector.contract_loader, "get_canonical_name") as mock:\n            result = detector.process(doc)\n            mock.assert_not_called()\n\n    def test_exception_during_canonicalization(self, detector):\n        """Exception in get_canonical_name is caught."""\n        doc = _make_doc(\n            blocks=[_b("1. Introduction", 0, font_size=18)],\n            template_name="ieee",\n        with patch.object(detector.contract_loader, "get_canonical_name",\n                          side_effect=RuntimeError("fail")):\n            result = detector.process(doc)\n        assert result is not None\n\n    def test_canonicalization_with_no_section_name(self, detector):\n        """Blocks without section_name are skipped."""\n        doc = _make_doc(\n            blocks=[\n                _b("1. Introduction", 0, font_size=18),\n                _b("Body text", 1, font_size=12),\n            ],\n            template_name="ieee",\n        with patch.object(detector.contract_loader, "get_canonical_name",\n                          return_value="canon_intro") as mock:\n            result = detector.process(doc)\n            assert mock.call_count >= 1\n\n\nclass TestProcessGaps:\n    """Cover process() method edge cases."""\n\n    def test_processing_stage_recorded(self, detector):\n        """Processing stage added with correct metadata."""\n        doc = _make_doc(blocks=[\n            _b("1. Introduction", 0, font_size=18),\n        ])\n        result = detector.process(doc)\n        assert len(result.processing_history) > 0\n        stage = result.processing_history[-1]\n        assert stage.stage_name == "structure_detection"\n        assert stage.status == "success"\n\n    def test_updated_at_set(self, detector):\n        """Document updated_at is set after processing."""\n        doc = _make_doc(blocks=[\n            _b("1. Introduction", 0, font_size=18),\n        ])\n        result = detector.process(doc)\n        assert result.updated_at is not None\n\n    def test_detected_headings_cleared_on_each_process(self, detector):\n        """detected_headings is overwritten on each process call."""\n        doc1 = _make_doc(blocks=[_b("1. Intro", 0, font_size=18)])\n        detector.process(doc1)\n        count1 = len(detector.detected_headings)\n\n        doc2 = _make_doc(blocks=[_b("Body text", 0, font_size=12)])\n        detector.process(doc2)\n        count2 = len(detector.detected_headings)\n        # Second doc has fewer or zero detected headings\n        assert count2 <= count1\n\n    def test_process_with_template_no_publisher(self, detector):\n        """Template without template_name -> no publisher."""\n        doc = PipelineDocument(\n            document_id="test",\n            blocks=[_b("1. Intro", 0, font_size=18)],\n            template=None,\n        result = detector.process(doc)\n        assert result is not None\n\n\nclass TestDetectHeadingCandidatesGaps:\n    """Cover edge cases in _detect_heading_candidates."""\n\n    def test_heading_with_metadata_level(self, detector):\n        """heading_level in metadata overrides inferred level."""\n        doc = _make_doc(blocks=[\n            _b("Paragraph", 0, font_size=12),\n            _b("Introduction", 1, font_size=18, bold=True,\n               metadata={"potential_heading": True, "heading_level": 2}),\n        ])\n        result = detector.process(doc)\n        assert result is not None\n        assert result.blocks[1].level == 2\n\n    def test_heading_position_boost(self, detector):\n        """Position-based confidence boost applied."""\n        doc = _make_doc(blocks=[\n            _b("1. Introduction", 0, font_size=18),\n        ])\n        result = detector.process(doc)\n        assert result is not None\n        assert result.blocks[0].metadata.get("heading_confidence", 0) > 0\n\n    def test_empty_blocks_skipped(self, detector):\n        """Blocks with empty text are skipped."""\n        doc = _make_doc(blocks=[\n            _b("", 0, font_size=12),\n            _b("   ", 1, font_size=12),\n            _b("1. Introduction", 2, font_size=18),\n        ])\n        result = detector.process(doc)\n        assert result is not None\n        assert result.blocks[2].metadata.get("is_heading_candidate") is True\n\n\nclass TestDoclingDetectionGaps:\n    """Cover remaining Docling detection edge cases."""\n\n    def test_element_no_bbox_handled(self, detector):\n        """Element without bbox is handled."""\n        element = {"text": "Title", "font_size": 24, "type": "title", "confidence": 0.9}\n        doc = _make_doc(\n            blocks=[_b("Title", 0, font_size=24)],\n            docling_elements=[element],\n        result = detector.process(doc)\n        assert result is not None\n\n    def test_empty_elements_returns_empty_candidates(self, detector):\n        """Empty elements list triggers fallback."""\n        doc = _make_doc(\n            blocks=[_b("Introduction", 0, font_size=18, bold=True)],\n            docling_elements=[],\n        result = detector.process(doc)\n        assert result is not None\n        assert result.blocks[0].metadata.get("is_heading_candidate") is True\n\n    def test_no_font_sizes_in_elements(self, detector):\n        """When no font_sizes found in title/heading elements, uses all elements."""\n        elements = [\n            {"text": "Intro", "font_size": 0, "type": "section_header", "bbox": {}, "confidence": 0.9},\n            {"text": "Body", "font_size": 12, "type": "text", "bbox": {}, "confidence": 0.9},\n        ]\n        doc = _make_doc(\n            blocks=[_b("Intro", 0, font_size=18)],\n            docling_elements=elements,\n        result = detector.process(doc)\n        assert result is not None\n\n    def test_block_no_element_match_skipped(self, detector):\n        """Block with no matching element is skipped in docling path."""\n        doc = _make_doc(\n            blocks=[\n                _b("Introduction", 0, font_size=18),\n                _b("Unmatched text", 1, font_size=12),\n            ],\n            docling_elements=[\n                {"text": "Introduction", "font_size": 18, "type": "section_header",\n                 "bbox": {}, "confidence": 0.9},\n            ]\n        result = detector.process(doc)\n        assert result is not None\n        assert result.blocks[0].metadata.get("is_heading_candidate") is True\n        assert result.blocks[1].metadata.get("is_heading_candidate") is None\n\n\nclass TestConvenienceWrapperGaps:\n    """Cover detect_structure() edge cases."""\n\n    def test_detect_structure_with_template(self):\n        """detect_structure works with template."""\n        doc = _make_doc(\n            blocks=[_b("1. Introduction", 0, font_size=18)],\n            template_name="ieee",\n        result = detect_structure(doc)\n        assert result is not None\n        assert result.blocks[0].metadata.get("is_heading_candidate") is True\n\n    def test_detect_structure_with_empty_doc(self):\n        """detect_structure works with empty document."""\n        doc = _make_doc(blocks=[])\n        result = detect_structure(doc)\n        assert result is not None\n\n    def test_detect_structure_safe_on_exception(self):\n        """safe_function catches error and returns None."""\n        result = detect_structure(None)\n        assert result is None\n\n    def test_detect_structure_with_docling(self):\n        """detect_structure uses Docling when available."""\n        doc = _make_doc(\n            blocks=[_b("Introduction", 0, font_size=18)],\n            docling_elements=[\n                {"text": "Introduction", "font_size": 18, "type": "section_header",\n                 "bbox": {}, "confidence": 0.9},\n            ]\n        result = detect_structure(doc)\n        assert result is not None\n        assert result.blocks[0].metadata.get("is_heading_candidate") is True\n\n\nclass TestDetectStructureWithDoclingGaps:\n    """Cover _detect_structure_with_docling edge cases not in existing tests."""\n\n    def test_elements_none(self, detector):\n        """None elements -> fallback to _detect_heading_candidates."""\n        with patch.object(detector, "_detect_heading_candidates", return_value=[]):\n            result = detector._detect_structure_with_docling(\n                [_b("Intro", 0, font_size=18)],\n                {"elements": None}\n        assert result == []\n\n    def test_empty_normalized_text_skipped(self, detector):\n        """Element with whitespace-only text is skipped."""\n        elements = [\n            {"text": "  ", "font_size": 18, "type": "section_header", "bbox": {}, "confidence": 0.9},\n        ]\n        with patch.object(detector, "_detect_heading_candidates", return_value=[]):\n            result = detector._detect_structure_with_docling(\n                [_b("Intro", 0, font_size=18)],\n                {"elements": elements}\n        assert result is not None\n\n    def test_block_text_norm_empty_skip(self, detector):\n        """Block with empty normalized text is skipped."""\n        elements = [\n            {"text": "Introduction", "font_size": 18, "type": "section_header",\n             "bbox": {}, "confidence": 0.9},\n        ]\n        with patch.object(detector, "_detect_heading_candidates", return_value=[]):\n            result = detector._detect_structure_with_docling(\n                [_b("", 0, font_size=18)],\n                {"elements": elements}\n        assert result == []\n\n    def test_no_title_or_heading_but_body_present(self, detector):\n        """Elements with only 'text' type, no title/heading."""\n        elements = [\n            {"text": "Plain body", "font_size": 12, "type": "text", "bbox": {}, "confidence": 0.9},\n        ]\n        with patch.object(detector, "_detect_heading_candidates", return_value=[]):\n            result = detector._detect_structure_with_docling(\n                [_b("Plain body", 0, font_size=12)],\n                {"elements": elements}\n        assert result == []\n\n    def test_section_header_with_specific_level(self, detector):\n        """Section headers at varying font sizes assign correct levels."""\n        elements = [\n            {"text": "Large Heading", "font_size": 20, "type": "section_header",\n             "bbox": {}, "confidence": 0.9},\n            {"text": "Medium Heading", "font_size": 17, "type": "section_header",\n             "bbox": {}, "confidence": 0.9},\n            {"text": "Small Heading", "font_size": 14, "type": "section_header",\n             "bbox": {}, "confidence": 0.9},\n            {"text": "Tiny Heading", "font_size": 11, "type": "section_header",\n             "bbox": {}, "confidence": 0.9},\n        ]\n        blocks = [\n            _b("Large Heading", 0, font_size=20),\n            _b("Medium Heading", 1, font_size=17),\n            _b("Small Heading", 2, font_size=14),\n            _b("Tiny Heading", 3, font_size=11),\n        ]\n        doc = _make_doc(blocks=blocks, docling_elements=elements)\n        result = detector.process(doc)\n        assert result is not None\n        assert result.blocks[0].level == 1\n        assert result.blocks[1].level == 2\n        assert result.blocks[2].level == 3\n        assert result.blocks[3].level == 4\n